const isBrowser = typeof window !== "undefined";
const NodeClass = isBrowser ? Node : function () {};

function createElementFunction(tag) {
  const fn = function (...args) {
    let attributes = {};
    let children = [];

    for (let i = 0; i < args.length; i++) {
      const arg = args[i];
      if (arg === null || arg === undefined) continue;

      if (
        i === 0 &&
        typeof arg === "object" &&
        !Array.isArray(arg) &&
        !(arg instanceof NodeClass) &&
        !arg.__isTagFunction
      ) {
        attributes = arg;
      } else {
        children.push(arg);
      }
    }

    let html = `<${tag}`;
    for (const [key, value] of Object.entries(attributes)) {
      if (value === true) {
        html += ` ${key}`;
      } else if (value !== false && value !== null && value !== undefined) {
        html += ` ${key}="${String(value).replace(/"/g, "&quot;")}"`;
      }
    }

    if (tagsVoid.includes(tag) && children.length === 0) {
      return `${html}/>`;
    }

    html += ">";
    for (const child of children) {
      if (child !== null && child !== undefined) {
        html += String(child);
      }
    }
    return html + `</${tag}>`;
  };

  fn.__isTagFunction = true;
  return fn;
}

// Replaces & < > " ' with entities, so text can't be read as markup
function escape(text) {
  if (text === null || text === undefined) return "";
  return String(text)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

